<?php
namespace App\Services;
use App\Models\{FundingRequest,LedgerEntry,User};
use Illuminate\Support\Facades\DB;
class FundingService {
 public function approve(FundingRequest $funding,User $admin,string $note=''):void{DB::transaction(function()use($funding,$admin,$note){$funding=FundingRequest::lockForUpdate()->findOrFail($funding->id);abort_unless(in_array($funding->status,['awaiting_transfer','under_review','awaiting_admin_review']),422,'Request is not ready for approval.');abort_if($funding->checks()->whereIn('result',['possible_match','blocked','error'])->exists(),422,'Resolve compliance alerts before approval.');$user=User::lockForUpdate()->findOrFail($funding->user_id);if($funding->type==='deposit'){$user->increment('cash_balance',(float)$funding->usd_amount);LedgerEntry::firstOrCreate(['idempotency_key'=>"funding:{$funding->id}:settled"],['user_id'=>$user->id,'funding_request_id'=>$funding->id,'direction'=>'credit','amount'=>$funding->usd_amount,'balance_after'=>$user->fresh()->cash_balance,'event'=>'deposit_settled']);}$funding->update(['status'=>'approved','review_note'=>$note,'reviewed_by'=>$admin->id,'reviewed_at'=>now()]);});}
 public function reject(FundingRequest $funding,User $admin,string $note):void{DB::transaction(function()use($funding,$admin,$note){$funding=FundingRequest::lockForUpdate()->findOrFail($funding->id);abort_if(in_array($funding->status,['approved','rejected']),422,'Request is already final.');if($funding->type==='withdrawal'){$user=User::lockForUpdate()->findOrFail($funding->user_id);$user->increment('cash_balance',(float)$funding->usd_amount);LedgerEntry::firstOrCreate(['idempotency_key'=>"funding:{$funding->id}:release"],['user_id'=>$user->id,'funding_request_id'=>$funding->id,'direction'=>'credit','amount'=>$funding->usd_amount,'balance_after'=>$user->fresh()->cash_balance,'event'=>'withdrawal_hold_released']);}$funding->update(['status'=>'rejected','review_note'=>$note,'reviewed_by'=>$admin->id,'reviewed_at'=>now()]);});}
}
